script:
frappe.ui.form.on('Production Task', {
	refresh(frm) {
		if (frm.doc.is_parent && frm.doc.task_subject == "Order Sample"){
		    frm.add_custom_button('Add New Sample', ()=>{
		        show_task_dialog(frm);
		    }).addClass("btn-primary");
		}
	}
})

async function show_task_dialog(frm){
    let milestone_options = [];

    await frappe.call({
      method: "production_system.apis.project_apis.get_project_milestones",
      args: {
        project_name: frm.doc.project
      },
      callback: function(r) {
        milestone_options = r.message;
        console.log("Milestones:", milestone_options);
      }
    });

	const d = new frappe.ui.Dialog({
		title: __("Create Task for Order Sampling"),
		fields: [
			{
				fieldtype: "Link",
				fieldname: "project",
				label: __("Production Project"),
				options: "Production Project",
				reqd: 1,
				hidden: 1,
				default: frm.doc.project
			},
			{
				fieldtype: "Link",
				fieldname: "parent_task",
				label: __("Select Parent"),
				options: "Production Task",
				get_query: function() {
					return {
						filters: [
							["Production Task", "project", "=", frm.doc.project],
							["Production Task", "is_parent", "=", true],
						]
					};
				},
				default: frm.doc.name,
				hidden: 1
			},
			{
				fieldtype: "Select",
				fieldname: "sampling_for",
				label: __("Sampling For"),
				reqd: 1,
				options: ['Fabric Sheet','Stone Sheet','Veneer Polish','PU Polish','Measurement/ Site Validation','Snag','CNC Sample']
			},
			{
				fieldtype: "Data",
				fieldname: "task_subject",
				label: __("Task Subject"),
				reqd: 1,
			},
			{
				// fieldtype: "Select",
				fieldtype: "Link",
				fieldname: "milestone",
				label: __("Milestone"),
				// options: milestone_options.length
				// 	? milestone_options
				// 	: ["No milestones available"],
				options: "Production Milestone",
				reqd: 1,
				default: milestone_options[0]
			},
			{
				// fieldtype: "Select",
				fieldtype: "Link",
				fieldname: "type",
				label: __("Type"),
				// options: milestone_options.length
				// 	? milestone_options
				// 	: ["No milestones available"],
				options: "Production Type",
				reqd: 1,
				// default: milestone_options[0]
			},
			{
				fieldtype: "Date",
				fieldname: "start_date",
				label: __("Start Date"),
				reqd: 1,
				default: "Today"
			},
			{ fieldtype: "Date", fieldname: "due_date", label: __("Due Date"), reqd: 1 },
			{
				fieldtype: "Link",
				options: "User",
				fieldname: "assigned_to",
				label: __("Assign To"),
			},
			{
				fieldtype: "Attach",
				fieldname: "attachment",
				label: __("Attachment"),
			},
		],
		primary_action_label: __("Create"),
		primary_action(values) {
			// Validation
			if (!values.task_subject) return frappe.msgprint(__("Please enter a Task Subject."));
			if (!values.start_date || !values.due_date)
				return frappe.msgprint(__("Please enter both start and due dates."));
			if (frappe.datetime.get_diff(values.due_date, values.start_date) < 0)
				return frappe.msgprint(__("Due Date must be the same or after Start Date."));
			if (!values.milestone || values.milestone === "No milestones available")
				return frappe.msgprint(__("Please select a milestone."));

			// Call server API to create task and link it on the project
			frappe.call({
				method: "production_system.api.create_direct_task",
				args: {
					project_name: values.project,
					task_subject: values.task_subject + ' (' + values.sampling_for + ')',
					start_date: values.start_date,
					due_date: values.due_date,
					assigned_to: values.assigned_to || "",
					milestone: values.milestone,
					type: values.type,
					parent_task: values.parent_task,
					attachment: values.attachment
				},
				freeze: true,
				freeze_message: __("Creating task and linking to project..."),
				callback: function (r) {
					if (!r.exc && r.message && r.message.ok) {
						d.hide();
						frappe.show_alert({
							message: __("Task created"),
							indicator: "green",
						});
						// Optionally reload or refresh the form to show new direct_tasks row
						frm.reload_doc && frm.reload_doc();
					} else {
						const msg =
							(r.message && r.message.message) || __("Could not create task");
						frappe.msgprint({
							title: __("Error"),
							message: msg,
							indicator: "red",
						});
					}
				},
			});
		},
	});
	d.show();

}
